"""Distinct functional local HTML Make starters, without hosted template claims."""
import html

WEB_FORMATS = {
    "dashboard": {"title": "本地仪表盘", "icon_key": "chartLine", "prompt": "Build a dashboard with actual user-supplied data or an explicitly available source. Include working charts and an accessible data table. Never invent live feeds or sample metrics presented as facts."},
    "design": {"title": "本地设计", "icon_key": "palette", "prompt": "Build the requested visual design as actual responsive HTML/SVG, with complete typography, colors and layout. Use only supplied or actually generated assets; label any missing content."},
    "animation": {"title": "本地动画", "icon_key": "playCircle", "prompt": "Build an actual working CSS/SVG/Canvas animation. Include a visible keyboard-operable play/pause control, honor prefers-reduced-motion, avoid flashing, and animate transform/opacity when practical."},
    "whiteboard": {"title": "本地图板", "icon_key": "shapes", "prompt": "Build an actual visual whiteboard or diagram in HTML/SVG/Canvas. Provide keyboard and single-tap alternatives for any drag interaction. Include a usable representation of its data that the user can copy into a follow-up Make request."},
    "checklist": {"title": "本地清单", "icon_key": "checklist", "prompt": "Build an actual interactive checklist with native labeled checkboxes, working completion state and useful edit controls. Include a representation of its current data that the user can copy into a follow-up Make request."},
}

STYLE = """*{box-sizing:border-box}body{margin:0;background:#f7f5f0;color:#202522;font:16px/1.6 system-ui;overflow-wrap:anywhere}main{max-width:64rem;margin:auto;padding:clamp(1rem,4vw,3rem)}h1{line-height:1.15;font-size:clamp(2rem,6vw,3.5rem)}form,.controls{display:flex;flex-wrap:wrap;gap:.75rem;align-items:end;margin:1rem 0}label{display:block}input,textarea,button,select{font:inherit;max-width:100%}input,textarea,select{padding:.6rem;border:1px solid #89958d;border-radius:.4rem}button{padding:.6rem 1rem;background:#175d47;color:white;border:0;border-radius:.4rem;cursor:pointer;min-height:44px}button:disabled{opacity:.5;cursor:default}:focus-visible{outline:3px solid #aa4600;outline-offset:3px}textarea{display:block;width:100%;min-height:7rem}section,.panel{background:white;border:1px solid #d1d9d2;border-radius:1rem;padding:1rem;margin:1rem 0}.hint{color:#40544b;font-size:.92rem}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:.5rem;border-bottom:1px solid #d1d9d2}caption{text-align:left;font-weight:bold}th:last-child,td:last-child{white-space:nowrap;min-width:4rem}svg{display:block;max-width:100%;height:auto}[hidden]{display:none!important}@media(forced-colors:active){button{border:1px solid ButtonText}}"""

STATE = '''<p class="hint">Changes in this view are temporary. To preserve a version, copy the current data below into a follow-up Make request and publish the revised artifact.</p><label for="state">Current data for a follow-up Make request</label><textarea id="state" readonly></textarea>'''

DASHBOARD = '''<p>Plot the data you enter. No live sources are connected and no metrics are prefilled.</p>
<form id="entry"><div><label for="label">Label</label><input id="label" required maxlength="50"></div><div><label for="value">Value (zero or greater)</label><input id="value" type="number" required min="0" max="1000000000000" step="any"></div><button id="add" type="button">Add data</button><button id="clear" type="button">Clear data</button></form>
<p id="status" role="status">Enter data to begin.</p><figure><figcaption>Values scaled against the largest entered value</figcaption><div id="bars" aria-hidden="true"></div></figure>
<table><caption>Entered data</caption><thead><tr><th scope="col">Label</th><th scope="col">Value</th></tr></thead><tbody id="rows"></tbody></table>''' + STATE + '''
<script>(()=>{const data=[];const byId=id=>document.getElementById(id);function draw(){byId('rows').replaceChildren();byId('bars').replaceChildren();const max=Math.max(1,...data.map(x=>x.value));for(const row of data){const tr=document.createElement('tr');for(const value of [row.label,row.value]){const cell=document.createElement('td');cell.textContent=value;tr.append(cell)}byId('rows').append(tr);const label=document.createElement('div');label.textContent=row.label+' · '+row.value;const bar=document.createElement('div');bar.style.cssText='height:1.25rem;background:#175d47;border-radius:.25rem;margin-bottom:1rem';bar.style.width=(100*row.value/max)+'%';byId('bars').append(label,bar)}byId('state').value=JSON.stringify(data,null,2);byId('status').textContent=data.length+' data points entered.'}localForm(byId('entry'),byId('add'),()=>{if(data.length>=32){byId('status').textContent='This starter supports 32 data points.';return}const label=byId('label').value.trim(),value=Number(byId('value').value);if(!label||!Number.isFinite(value)||value<0||value>1e12)return;data.push({label,value});draw();byId('entry').reset();byId('label').focus()});byId('clear').addEventListener('click',()=>{data.length=0;draw()});byId('state').value='[]'})()</script>'''

DESIGN = '''<p>A local poster composition. Edit its headline and accent color, then ask Make to publish the version you want to retain.</p>
<div id="design-controls" class="controls"><div><label for="headline">Poster headline</label><input id="headline" maxlength="200" value="__TITLE__"></div><div><label for="accent">Accent color</label><input id="accent" type="color" value="#175d47"></div></div>
<section id="poster" style="background:#142b24;color:#fff;min-height:30rem;position:relative;overflow:hidden;padding:clamp(1.5rem,7vw,5rem);--accent:#175d47"><svg aria-hidden="true" viewBox="0 0 600 180"><circle cx="480" cy="80" r="110" fill="var(--accent)"/><circle cx="410" cy="80" r="55" fill="#eadbb2"/></svg><p style="text-transform:uppercase;letter-spacing:.2em">Local design</p><h2 id="poster-title" style="position:relative;font-size:clamp(2rem,7vw,5rem);line-height:1.1;max-width:14ch">__TITLE__</h2><p>Shape · Space · Type</p></section>
<p class="hint">This preview changes only the current view; the saved artifact changes when Make publishes a revision.</p>
<script>(()=>{document.getElementById('headline').addEventListener('input',e=>{document.getElementById('poster-title').textContent=e.target.value});document.getElementById('accent').addEventListener('input',e=>{document.getElementById('poster').style.setProperty('--accent',e.target.value)})})()</script>'''

ANIMATION = '''<p>An actual local orbital animation. Start or pause it with the control below.</p><button id="toggle" type="button">Play animation</button><p id="motion-status" role="status">Paused.</p>
<section><svg role="img" aria-label="A circle orbiting a central shape" viewBox="0 0 600 320"><circle cx="300" cy="160" r="100" fill="none" stroke="#a1b9ad" stroke-width="2"/><circle cx="300" cy="160" r="45" fill="#175d47"/><g id="orbit"><circle cx="400" cy="160" r="20" fill="#bc622a"/></g></svg></section>
<style>#orbit{transform-origin:300px 160px}@keyframes orbit{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:no-preference){#orbit{animation:orbit 5s linear infinite;animation-play-state:paused}.running #orbit{animation-play-state:running}}</style>
<script>(()=>{const button=document.getElementById('toggle'),status=document.getElementById('motion-status'),preference=matchMedia('(prefers-reduced-motion: reduce)');let running=false;function sync(){if(preference.matches)running=false;document.body.classList.toggle('running',running);button.disabled=preference.matches;button.textContent=running?'Pause animation':'Play animation';status.textContent=preference.matches?'Reduced motion is enabled; the scene remains still.':running?'Playing.':'Paused.'}button.addEventListener('click',()=>{running=!running;sync()});preference.addEventListener('change',sync);sync()})()</script>'''

CHECKLIST = '''<p>Add items and mark them complete. This starter does not create background tasks or reminders.</p><form id="entry"><div><label for="task">Checklist item</label><input id="task" required maxlength="300"></div><button id="add" type="button">Add item</button></form><p id="status" role="status">No items yet.</p><fieldset><legend>Checklist items</legend><div id="items"></div></fieldset>''' + STATE + '''
<script>(()=>{const items=[],byId=id=>document.getElementById(id);let next=0;function sync(){byId('state').value=JSON.stringify(items.map(({text,done})=>({text,done})),null,2);byId('status').textContent=items.filter(x=>x.done).length+' of '+items.length+' complete.'}localForm(byId('entry'),byId('add'),()=>{const text=byId('task').value.trim();if(!text)return;if(items.length>=100){byId('status').textContent='This starter supports 100 items.';return}const item={text,done:false,id:++next},row=document.createElement('div');row.className='controls';const input=document.createElement('input');input.type='checkbox';input.id='check-'+item.id;const label=document.createElement('label');label.htmlFor=input.id;label.textContent=text;const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.setAttribute('aria-label','Remove item '+item.id+': '+text);input.addEventListener('change',()=>{item.done=input.checked;sync()});remove.addEventListener('click',()=>{items.splice(items.indexOf(item),1);row.remove();sync();byId('task').focus()});row.append(input,label,remove);byId('items').append(row);items.push(item);sync();byId('entry').reset();byId('task').focus()});byId('state').value='[]'})()</script>'''

WHITEBOARD = '''<p>Add notes and arrange them on the board. Move a note using its handle with pointer drag or arrow keys, or use its direction buttons.</p><form id="entry"><div><label for="note">Note text</label><input id="note" required maxlength="300"></div><button id="add" type="button">Add note</button></form><p id="status" role="status">No notes yet.</p><section id="board" aria-label="Note board" style="height:34rem;position:relative;background:repeating-linear-gradient(0deg,#e7ece6 0px,#e7ece6 1px,transparent 1px,transparent 24px)"></section>
<style>.note{position:absolute;inset:0 auto auto 0;width:15rem;max-width:100%;padding:.5rem;background:#f5e4a6;border:1px solid #77633e;border-radius:.5rem}.note p{max-height:7rem;overflow:auto;margin:.4rem}.note button{padding:.3rem .5rem}.handle{cursor:grab;touch-action:none;-webkit-user-select:none;user-select:none}.handle.dragging{cursor:grabbing}.note .controls{gap:.2rem;margin:.3rem 0}</style>''' + STATE + '''
<script>(()=>{const notes=[],byId=id=>document.getElementById(id),board=byId('board');let next=0;function sync(){byId('state').value=JSON.stringify(notes.map(({text,x,y})=>({text,x,y})),null,2)}function move(note,x,y,announce=false){note.x=Math.max(0,Math.min(x,board.clientWidth-note.element.offsetWidth));note.y=Math.max(0,Math.min(y,board.clientHeight-note.element.offsetHeight));note.element.style.transform='translate('+note.x+'px,'+note.y+'px)';sync();if(announce)byId('status').textContent='Note '+note.id+' moved.'}localForm(byId('entry'),byId('add'),()=>{const text=byId('note').value.trim();if(!text)return;if(notes.length>=20){byId('status').textContent='This starter supports 20 notes.';return}const element=document.createElement('article');element.className='note';const note={text,x:0,y:0,id:++next,element};const handle=document.createElement('button');handle.type='button';handle.className='handle';handle.textContent='Move note '+note.id;handle.setAttribute('aria-label','Move note '+note.id+'. Use arrow keys to move.');const content=document.createElement('p');content.textContent=text;const controls=document.createElement('div');controls.className='controls';for(const [label,dx,dy] of [['Left',-15,0],['Up',0,-15],['Down',0,15],['Right',15,0]]){const button=document.createElement('button');button.type='button';button.textContent=label;button.setAttribute('aria-label',label+' for note '+note.id);button.addEventListener('click',()=>move(note,note.x+dx,note.y+dy,true));controls.append(button)}let offset=null;handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;offset={x:e.clientX-note.x,y:e.clientY-note.y};handle.setPointerCapture(e.pointerId);handle.classList.add('dragging')});handle.addEventListener('pointermove',e=>{if(offset&&handle.hasPointerCapture(e.pointerId))move(note,e.clientX-offset.x,e.clientY-offset.y)});handle.addEventListener('pointerup',e=>{if(handle.hasPointerCapture(e.pointerId))handle.releasePointerCapture(e.pointerId)});handle.addEventListener('pointercancel',()=>{offset=null;handle.classList.remove('dragging')});handle.addEventListener('lostpointercapture',()=>{offset=null;handle.classList.remove('dragging');byId('status').textContent='Note '+note.id+' moved.'});handle.addEventListener('keydown',e=>{const delta={ArrowLeft:[-15,0],ArrowRight:[15,0],ArrowUp:[0,-15],ArrowDown:[0,15]}[e.key];if(delta){e.preventDefault();move(note,note.x+delta[0],note.y+delta[1],true)}});element.append(handle,content,controls);board.append(element);notes.push(note);move(note,notes.length*15,notes.length*15);byId('status').textContent='Note '+note.id+' added.';byId('entry').reset();byId('note').focus()});window.addEventListener('resize',()=>notes.forEach(n=>move(n,n.x,n.y)));byId('state').value='[]'})()</script>'''

LOCAL_FORM = """<script>function localForm(form,button,handler){button.addEventListener('click',()=>{if(form.reportValidity())handler()});form.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.tagName==='INPUT'){event.preventDefault();button.click()}});form.addEventListener('submit',event=>event.preventDefault())}</script>"""

TEMPLATES = {"dashboard": DASHBOARD, "design": DESIGN, "animation": ANIMATION, "whiteboard": WHITEBOARD, "checklist": CHECKLIST}


def starter(kind, title):
    body = TEMPLATES[kind].replace("__TITLE__", html.escape(title, quote=True))
    return ('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            '<meta name="duet-make-family" content="' + kind + '"><title>' + html.escape(title) + '</title><style>' + STYLE
            + '</style>' + LOCAL_FORM + '</head><body><main><h1>' + html.escape(title) + '</h1>' + body
            + '<noscript>This interactive starter needs JavaScript. Ask Make to create a static version if needed.</noscript></main></body></html>').encode('utf-8')
